=== FILE: sync_fifo.v ===
`timescale 1ns / 1ps
// sync_fifo: parameterizable single-clock FIFO with first-word fall-through.
// Implements interface_spec.md per microarchitecture.md:
//   - storage `mem` (not reset), pointers wrapping at DEPTH-1 by compare,
//   - explicit occupancy register `count_q` driving full/empty/count,
//   - requests gated by the flags (write while full / read while empty dropped),
//   - combinational read of the oldest slot,
//   - synchronous, active-low reset clearing pointers and count.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer PW     = $clog2(DEPTH);
    localparam integer CW     = $clog2(DEPTH + 1);
    localparam integer LAST_I = DEPTH - 1;
    localparam integer ONE_I  = 1;

    localparam [PW-1:0] LAST_P  = LAST_I[PW-1:0];
    localparam [PW-1:0] ONE_P   = ONE_I[PW-1:0];
    localparam [CW-1:0] DEPTH_C = DEPTH[CW-1:0];
    localparam [CW-1:0] ONE_C   = ONE_I[CW-1:0];

    reg  [WIDTH-1:0] mem [0:DEPTH-1];

    reg  [PW-1:0]    wr_ptr_q;
    reg  [PW-1:0]    wr_ptr_d;
    reg  [PW-1:0]    rd_ptr_q;
    reg  [PW-1:0]    rd_ptr_d;
    reg  [CW-1:0]    count_q;
    reg  [CW-1:0]    count_d;

    wire             wr_acc;
    wire             rd_acc;

    // Flags are compares on a register: no combinational path from inputs.
    assign full    = (count_q == DEPTH_C);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;

    // First-word fall-through read of the oldest entry.
    assign rd_data = mem[rd_ptr_q];

    // Overflow / underflow policy: the flags gate the requests.
    assign wr_acc  = wr_en & ~full;
    assign rd_acc  = rd_en & ~empty;

    // Next write pointer: wrap at DEPTH-1 by compare, not by overflow.
    always @* begin
        wr_ptr_d = wr_ptr_q;
        if (wr_acc) begin
            if (wr_ptr_q == LAST_P) begin
                wr_ptr_d = {PW{1'b0}};
            end else begin
                wr_ptr_d = wr_ptr_q + ONE_P;
            end
        end
    end

    // Next read pointer.
    always @* begin
        rd_ptr_d = rd_ptr_q;
        if (rd_acc) begin
            if (rd_ptr_q == LAST_P) begin
                rd_ptr_d = {PW{1'b0}};
            end else begin
                rd_ptr_d = rd_ptr_q + ONE_P;
            end
        end
    end

    // Next occupancy: moves only by accepted requests.
    always @* begin
        case ({wr_acc, rd_acc})
            2'b10:   count_d = count_q + ONE_C;
            2'b01:   count_d = count_q - ONE_C;
            default: count_d = count_q;
        endcase
    end

    // Control registers, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= {PW{1'b0}};
            rd_ptr_q <= {PW{1'b0}};
            count_q  <= {CW{1'b0}};
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
        end
    end

    // Storage: datapath, not reset, written only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr_q] <= wr_data;
        end
    end

`ifdef FORMAL
    // Design-intent properties (interface_spec.md section 7). Not proven by
    // the RTL implementation task.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    (* anyconst *) reg [PW-1:0] f_addr;
    reg  [WIDTH-1:0] f_data;
    reg              f_was_full;
    wire [CW:0]      f_sum;
    wire [CW:0]      f_wr_exp;
    wire [CW:0]      f_dist;
    wire             f_in_use;

    assign f_sum    = rd_ptr_q + count_q;
    assign f_wr_exp = (f_sum >= DEPTH) ? (f_sum - DEPTH) : f_sum;
    assign f_dist   = (f_addr >= rd_ptr_q) ? (f_addr - rd_ptr_q)
                                           : (f_addr + DEPTH - rd_ptr_q);
    assign f_in_use = (f_dist < count_q);

    always @(*) assume(f_addr <= LAST_P);

    always @(posedge clk) begin
        if (rst_n && wr_acc && (wr_ptr_q == f_addr)) f_data <= wr_data;
    end

    always @(posedge clk) begin
        if (!rst_n)    f_was_full <= 1'b0;
        else if (full) f_was_full <= 1'b1;
    end

    always @(*) begin
        if (f_past_valid) begin
            assert(full  == (count_q == DEPTH_C));
            assert(empty == (count_q == {CW{1'b0}}));
            assert(!(full && empty));
            assert(count_q  <= DEPTH_C);
            assert(wr_ptr_q <= LAST_P);
            assert(rd_ptr_q <= LAST_P);
            assert(wr_ptr_q == f_wr_exp);
            if (f_in_use) begin
                assert(mem[f_addr] == f_data);
                if (rd_ptr_q == f_addr) assert(rd_data == f_data);
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(count_q  == {CW{1'b0}});
                assert(wr_ptr_q == {PW{1'b0}});
                assert(rd_ptr_q == {PW{1'b0}});
            end else begin
                case ({$past(wr_acc), $past(rd_acc)})
                    2'b10:   assert(count_q == $past(count_q) + ONE_C);
                    2'b01:   assert(count_q == $past(count_q) - ONE_C);
                    default: assert(count_q == $past(count_q));
                endcase
                if ($past(full) && $past(wr_en))
                    assert(wr_ptr_q == $past(wr_ptr_q));
                if ($past(empty) && $past(rd_en))
                    assert(rd_ptr_q == $past(rd_ptr_q));
                if ($past(full) && $past(wr_en) && !$past(rd_en))
                    assert(count_q == $past(count_q));
                if ($past(empty) && $past(rd_en) && !$past(wr_en))
                    assert(count_q == $past(count_q));
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover(full);
            cover(f_was_full && empty);
            cover(f_in_use && (rd_ptr_q == f_addr) && rd_en);
        end
    end
`endif

endmodule
=== END FILE ===
