`timescale 1ns / 1ps
// sync_fifo_tb: self-checking testbench for sync_fifo.
// Two DUTs on one stimulus: DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12.
// Each has a reference-queue checker (sync_fifo_tb_checker) that checks
// full, empty, count and rd_data every cycle and records coverage bins.
module sync_fifo_tb;

    reg         clk;
    reg         rst_n;
    reg         wr_en;
    reg         rd_en;
    reg  [11:0] wr_data;
    reg  [11:0] dval;

    wire        full8;
    wire        empty8;
    wire [3:0]  count8;
    wire [7:0]  rd_data8;
    wire        full5;
    wire        empty5;
    wire [2:0]  count5;
    wire [11:0] rd_data5;

    wire [31:0] pass8;
    wire [31:0] fail8;
    wire [31:0] pass5;
    wire [31:0] fail5;
    wire [9:0]  cov8;
    wire [9:0]  cov5;

    reg [8*64-1:0] nonce;
    reg [31:0]  rnd;
    reg [31:0]  rnd2;
    reg [6:0]   wr_thr;
    reg [6:0]   rd_thr;
    integer     seed;
    integer     n;
    integer     passed;
    integer     failed;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) u_fifo8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data[7:0]),
        .full    (full8),
        .rd_en   (rd_en),
        .rd_data (rd_data8),
        .empty   (empty8),
        .count   (count8)
    );

    sync_fifo #(.DEPTH(5), .WIDTH(12)) u_fifo5 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full5),
        .rd_en   (rd_en),
        .rd_data (rd_data5),
        .empty   (empty5),
        .count   (count5)
    );

    sync_fifo_tb_checker #(.DEPTH(8), .WIDTH(8)) u_chk8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data[7:0]),
        .rd_en   (rd_en),
        .full    (full8),
        .empty   (empty8),
        .count   (count8),
        .rd_data (rd_data8),
        .n_pass  (pass8),
        .n_fail  (fail8),
        .cov     (cov8)
    );

    sync_fifo_tb_checker #(.DEPTH(5), .WIDTH(12)) u_chk5 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .rd_en   (rd_en),
        .full    (full5),
        .empty   (empty5),
        .count   (count5),
        .rd_data (rd_data5),
        .n_pass  (pass5),
        .n_fail  (fail5),
        .cov     (cov5)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Drive one cycle of inputs; they change on the falling edge and are
    // sampled by the DUTs and the models on the next rising edge.
    task drive;
        input       r;
        input       we;
        input       re;
        input [11:0] wd;
        begin
            @(negedge clk);
            rst_n   = r;
            wr_en   = we;
            rd_en   = re;
            wr_data = wd;
        end
    endtask

    task wr_only;
        begin
            dval = dval + 12'd1;
            drive(1'b1, 1'b1, 1'b0, dval);
        end
    endtask

    task rd_only;
        begin
            drive(1'b1, 1'b0, 1'b1, 12'h000);
        end
    endtask

    task wr_rd;
        begin
            dval = dval + 12'd1;
            drive(1'b1, 1'b1, 1'b1, dval);
        end
    endtask

    task idle;
        begin
            drive(1'b1, 1'b0, 1'b0, 12'h000);
        end
    endtask

    task in_reset;
        begin
            dval = dval + 12'd1;
            drive(1'b0, 1'b1, 1'b1, dval);
        end
    endtask

    initial begin
        rst_n   = 1'b0;
        wr_en   = 1'b0;
        rd_en   = 1'b0;
        wr_data = 12'h000;
        dval    = 12'h3a0;
        wr_thr  = 7'd64;
        rd_thr  = 7'd64;
        rnd     = 32'd0;
        rnd2    = 32'd0;
        seed    = 20261114;
        passed  = 0;
        failed  = 0;
        nonce   = {(8*64){1'b0}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            nonce[39:0] = "unset";
        end

        // Reset with requests asserted: requests during reset are ignored.
        in_reset;
        in_reset;
        in_reset;

        // Read while empty: ignored.
        rd_only;
        rd_only;

        // Write and read together when empty: only the write is accepted.
        wr_rd;
        idle;

        // Drain the single entry to empty.
        rd_only;

        // Fill both FIFOs to full, then keep writing (write while full).
        repeat (11) wr_only;

        // Write and read together when full (only the read), then in between.
        repeat (2) wr_rd;
        idle;

        // Drain to empty, then keep reading (read while empty).
        repeat (12) rd_only;

        // Partial fill, then back-to-back write and read in between.
        repeat (3) wr_only;
        repeat (4) wr_rd;
        repeat (2) wr_only;

        // Reset during traffic.
        in_reset;
        in_reset;
        idle;

        // Traffic after reset, crossing the wrap point again.
        repeat (6) wr_only;
        repeat (2) rd_only;
        repeat (4) wr_rd;
        repeat (9) rd_only;
        in_reset;

        // Random traffic with biased phases and occasional resets.
        for (n = 0; n < 4000; n = n + 1) begin
            case ((n / 200) % 4)
                0: begin wr_thr = 7'd115; rd_thr = 7'd40;  end
                1: begin wr_thr = 7'd40;  rd_thr = 7'd115; end
                2: begin wr_thr = 7'd90;  rd_thr = 7'd90;  end
                default: begin wr_thr = 7'd127; rd_thr = 7'd127; end
            endcase
            rnd  = $random(seed);
            rnd2 = $random(seed);
            drive(rnd[31:23] != 9'd0, rnd[6:0] < wr_thr, rnd[13:7] < rd_thr,
                  rnd2[11:0]);
        end

        idle;
        idle;
        repeat (2) @(negedge clk);
        #1;

        passed = pass8 + pass5;
        failed = fail8 + fail5;

        // Coverage bins, LSB first: full, write while full, read while empty,
        // drain to empty, both when empty, both when full, both in between,
        // write pointer wrap, read pointer wrap, reset while not empty.
        if (cov8 == 10'h3ff) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("sync_fifo_tb: DEPTH=8 coverage incomplete, bins reached %b", cov8);
        end
        if (cov5 == 10'h3ff) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("sync_fifo_tb: DEPTH=5 coverage incomplete, bins reached %b", cov5);
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
