`timescale 1ns / 1ps
// sync_fifo_tb_checker: reference-queue model, per-cycle output checks and
// coverage bins for one sync_fifo instance. Testbench only.
// The model is a circular buffer of 2^CW entries (CW = $clog2(DEPTH+1)),
// so it never relies on the DUT's mod-DEPTH pointer scheme.
module sync_fifo_tb_checker #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    input  wire                       rd_en,
    input  wire                       full,
    input  wire                       empty,
    input  wire [$clog2(DEPTH+1)-1:0] count,
    input  wire [WIDTH-1:0]           rd_data,
    output reg  [31:0]                n_pass,
    output reg  [31:0]                n_fail,
    output wire [9:0]                 cov
);

    localparam integer CW    = $clog2(DEPTH + 1);
    localparam integer ONE_I = 1;

    localparam [CW-1:0] FULL_C = DEPTH[CW-1:0];
    localparam [CW-1:0] ONE_C  = ONE_I[CW-1:0];
    localparam [CW-1:0] ZERO_C = {CW{1'b0}};

    reg [WIDTH-1:0] q [0:(1<<CW)-1];
    reg [CW-1:0]    h;
    reg [CW-1:0]    mc;
    reg             seen_rst;
    reg             wa;
    reg             ra;
    integer         wr_tot;
    integer         rd_tot;

    reg c_full;
    reg c_wr_full;
    reg c_rd_empty;
    reg c_drain;
    reg c_both_empty;
    reg c_both_full;
    reg c_both_mid;
    reg c_wrap_w;
    reg c_wrap_r;
    reg c_rst_busy;

    assign cov = {c_rst_busy, c_wrap_r, c_wrap_w, c_both_mid, c_both_full,
                  c_both_empty, c_drain, c_rd_empty, c_wr_full, c_full};

    // Model update on the rising edge, from the inputs and the model's own
    // pre-edge state.
    task model_step;
        begin
            if (!rst_n) begin
                if (seen_rst && (mc != ZERO_C)) c_rst_busy = 1'b1;
                h        = ZERO_C;
                mc       = ZERO_C;
                wr_tot   = 0;
                rd_tot   = 0;
                seen_rst = 1'b1;
            end else if (seen_rst) begin
                wa = wr_en && (mc != FULL_C);
                ra = rd_en && (mc != ZERO_C);
                if (wr_en && (mc == FULL_C)) c_wr_full = 1'b1;
                if (rd_en && !wr_en && (mc == ZERO_C)) c_rd_empty = 1'b1;
                if (wr_en && rd_en) begin
                    if (mc == ZERO_C)      c_both_empty = 1'b1;
                    else if (mc == FULL_C) c_both_full  = 1'b1;
                    else                   c_both_mid   = 1'b1;
                end
                if (ra && !wa && (mc == ONE_C)) c_drain = 1'b1;
                if (wa && ((wr_tot % DEPTH) == (DEPTH - 1))) c_wrap_w = 1'b1;
                if (ra && ((rd_tot % DEPTH) == (DEPTH - 1))) c_wrap_r = 1'b1;
                if (ra) begin
                    h      = h + ONE_C;
                    mc     = mc - ONE_C;
                    rd_tot = rd_tot + 1;
                end
                if (wa) begin
                    q[h + mc] = wr_data;
                    mc        = mc + ONE_C;
                    wr_tot    = wr_tot + 1;
                end
                if (mc == FULL_C) c_full = 1'b1;
            end
        end
    endtask

    // Output checks on the falling edge, against the model state after the
    // last rising edge.
    task check_outputs;
        begin
            if (full !== (mc == FULL_C)) begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo DEPTH=%0d: full is %b, expected %b (model count %0d)",
                       DEPTH, full, (mc == FULL_C), mc);
            end else begin
                n_pass = n_pass + 32'd1;
            end

            if (empty !== (mc == ZERO_C)) begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo DEPTH=%0d: empty is %b, expected %b (model count %0d)",
                       DEPTH, empty, (mc == ZERO_C), mc);
            end else begin
                n_pass = n_pass + 32'd1;
            end

            if (count !== mc) begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo DEPTH=%0d: count is %0d, expected %0d",
                       DEPTH, count, mc);
            end else begin
                n_pass = n_pass + 32'd1;
            end

            if (full === 1'b1 && empty === 1'b1) begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo DEPTH=%0d: full and empty are both high", DEPTH);
            end else begin
                n_pass = n_pass + 32'd1;
            end

            if (mc != ZERO_C) begin
                if (rd_data !== q[h]) begin
                    n_fail = n_fail + 32'd1;
                    $error("sync_fifo DEPTH=%0d: rd_data is %h, expected %h (model count %0d)",
                           DEPTH, rd_data, q[h], mc);
                end else begin
                    n_pass = n_pass + 32'd1;
                end
            end
        end
    endtask

    initial begin
        h            = ZERO_C;
        mc           = ZERO_C;
        seen_rst     = 1'b0;
        wa           = 1'b0;
        ra           = 1'b0;
        wr_tot       = 0;
        rd_tot       = 0;
        n_pass       = 32'd0;
        n_fail       = 32'd0;
        c_full       = 1'b0;
        c_wr_full    = 1'b0;
        c_rd_empty   = 1'b0;
        c_drain      = 1'b0;
        c_both_empty = 1'b0;
        c_both_full  = 1'b0;
        c_both_mid   = 1'b0;
        c_wrap_w     = 1'b0;
        c_wrap_r     = 1'b0;
        c_rst_busy   = 1'b0;
        forever begin
            @(posedge clk);
            model_step;
            @(negedge clk);
            if (seen_rst) check_outputs;
        end
    end

endmodule
